package com.muddakir.quran;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;
public class WirdWidget extends AppWidgetProvider{private static final String A="com.muddakir.quran.ADD_PAGE",P="quran_progress_prefs",K="wird_page";public void onUpdate(Context c,AppWidgetManager m,int[] ids){refresh(c,m,ids);}public void onReceive(Context c,Intent i){super.onReceive(c,i);if(A.equals(i.getAction())){SharedPreferences p=c.getSharedPreferences(P,0);int n=p.getInt(K,1)+1;if(n>604)n=1;p.edit().putInt(K,n).apply();refreshAll(c);}}public static void refreshAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);refresh(c,m,m.getAppWidgetIds(new ComponentName(c,WirdWidget.class)));}private static void refresh(Context c,AppWidgetManager m,int[] ids){int n=c.getSharedPreferences(P,0).getInt(K,1);for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_wird_layout);v.setTextViewText(R.id.txt_wird_count,"صفحة "+n+" / 604");Intent i=new Intent(c,WirdWidget.class).setAction(A);v.setOnClickPendingIntent(R.id.btn_add_page,PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}}}
